/**
 * The instrument: a few oscillators, an envelope and a room, in Float64.
 *
 * ═══ WHY THE GAME SYNTHESISES ITS OWN MUSIC ═══
 *
 * Or, twice, about sounds that were generated by asking a model for them:
 * *"the sounds are no good and not pleasant to the ear"*, and then — of five
 * attempts — *"2 of them were error sounds."* He was right both times, and
 * the fault was the method rather than the wording. That model is an EFFECTS
 * model: footsteps, doors, explosions. A fanfare is not an effect. It is
 * music — exact pitches, an exact interval, one chosen timbre, nothing else
 * — and asked for two warm notes, a texture model returns a texture.
 *
 * So these are computed. Every number here is a decision that can be
 * defended and changed — a pitch, an interval, a decay — instead of a
 * sentence somebody hopes lands. It also costs nothing to try the next one,
 * which matters when the brief is "fun" and the only test is whether a
 * seven-year-old grins.
 *
 * ═══ THE ONE RULE THAT CAME OUT OF GETTING IT WRONG ═══
 *
 * A sting that FALLS is an error sound. Two of the five rejected ones fell,
 * and one of those was a descending minor third — which is the sound of a
 * doorbell for "no". Every fanfare in this game RISES and lands on a major
 * chord, and nothing resolves downwards.
 *
 * Used by the Asulins ident (studioSting.ts) and by the game's own fanfares
 * (fanfare.ts), which is why it lives apart from both.
 */
const RATE = 44100;

/* ── the instrument ────────────────────────────────────────────────── */

export type Buf = Float64Array;

export const seconds = (n: number) => Math.round(n * RATE);
export const make = (dur: number): Buf => new Float64Array(seconds(dur));

/** Equal temperament from A4 = 440, so intervals are exact rather than eyeballed. */
export function note(name: string): number {
  const STEPS: Record<string, number> = {
    C: -9, "C#": -8, D: -7, "D#": -6, E: -5, F: -4,
    "F#": -3, G: -2, "G#": -1, A: 0, "A#": 1, B: 2,
  };
  const m = /^([A-G]#?)(-?\d)$/.exec(name);
  if (!m) throw new Error(`not a note: ${name}`);
  const semis = STEPS[m[1]!]! + (Number(m[2]) - 4) * 12;
  return 440 * Math.pow(2, semis / 12);
}

/**
 * An exponential decay with a short attack.
 *
 * The attack is 4ms rather than zero on purpose: a waveform that starts at
 * full amplitude starts with a CLICK, and a click is the difference between
 * a bell and a bug.
 */
export function env(i: number, n: number, attack = 0.004, decay = 3.5): number {
  const t = i / RATE;
  const a = Math.min(1, t / attack);
  return a * Math.exp((-decay * i) / n);
}

/**
 * One FM bell.
 *
 * Two oscillators: a carrier at the pitch, and a modulator at `ratio` times
 * it bending the carrier's phase. The modulator's own envelope decays faster
 * than the note, which is what a real struck bell does — bright at the strike
 * and pure as it rings out. A sine alone sounds like a test tone.
 */
export function bell(
  freq: number,
  dur: number,
  { ratio = 2.0, index = 3.2, decay = 3.6, gain = 1 } = {},
): Buf {
  const n = seconds(dur);
  const out = make(dur);
  for (let i = 0; i < n; i++) {
    const t = i / RATE;
    const mi = index * Math.exp((-decay * 2.2 * i) / n);
    const mod = Math.sin(2 * Math.PI * freq * ratio * t) * mi;
    out[i] = Math.sin(2 * Math.PI * freq * t + mod) * env(i, n, 0.004, decay) * gain;
  }
  return out;
}

/** A low body note: a few harmonics, no brightness. The thud under a hit. */
export function thud(freq: number, dur: number, { decay = 4.2, gain = 1 } = {}): Buf {
  const n = seconds(dur);
  const out = make(dur);
  for (let i = 0; i < n; i++) {
    const t = i / RATE;
    // A touch of downward pitch bend — every drum does it, and it is most of
    // why a flat sine sounds synthetic and a bent one sounds hit.
    const f = freq * (1 + 0.28 * Math.exp((-14 * i) / n));
    const s =
      Math.sin(2 * Math.PI * f * t) +
      0.34 * Math.sin(4 * Math.PI * f * t) +
      0.12 * Math.sin(6 * Math.PI * f * t);
    out[i] = (s / 1.46) * env(i, n, 0.002, decay) * gain;
  }
  return out;
}

/** Filtered noise, for a whoosh or the air around a hit. */
export function air(dur: number, { cutoff = 2600, decay = 3, gain = 1, rise = false } = {}): Buf {
  const n = seconds(dur);
  const out = make(dur);
  let lp = 0;
  let seed = 12345;
  for (let i = 0; i < n; i++) {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    const white = (seed / 0x3fffffff) - 1;
    const k = Math.min(1, (2 * Math.PI * cutoff) / RATE);
    lp += k * (white - lp);
    const shape = rise ? Math.pow(i / n, 2.2) : env(i, n, 0.002, decay);
    out[i] = lp * shape * gain;
  }
  return out;
}

/** Lay one sound into another at a time offset. */
export function at(into: Buf, src: Buf, start: number): void {
  const o = seconds(start);
  for (let i = 0; i < src.length && o + i < into.length; i++) into[o + i]! += src[i]!;
}

/**
 * A small room.
 *
 * ═══ PARALLEL AND DAMPED, WHICH THE FIRST VERSION WAS NEITHER ═══
 *
 * It was four feedback combs applied to the same buffer IN PLACE, one after
 * another, with no damping. Two things wrong with that, and the spectrogram
 * showed both: applied in series each comb feeds the next, so they compound
 * into a resonator rather than a room; and with no damping the high partials
 * ring as long as the low ones, which nothing real does. The decay came out
 * striped with fixed resonances — the sound of a metal pipe, which is a fair
 * description of "not pleasant to the ear".
 *
 * Schroeder's arrangement instead: the combs run in PARALLEL from the dry
 * signal and are summed, then two allpasses in series smear what is left.
 * The delays are mutually prime in samples so their resonances do not line
 * up and reinforce each other, and each comb's feedback path is lowpassed,
 * so the room swallows the bright partials first — which is what air does.
 */
export function room(src: Buf, { mix = 0.22, size = 1, damp = 0.32 } = {}): Buf {
  const n = src.length;
  const wet = new Float64Array(n);

  // Mutually prime lengths. Shared factors put two combs' resonances on top
  // of each other, which is the ringing this is here to avoid.
  const combs = [1327, 1733, 2113, 2591, 2927].map((d) => Math.max(1, Math.round(d * size)));
  for (const d of combs) {
    const buf = new Float64Array(d);
    let lp = 0;
    let i = 0;
    for (let j = 0; j < n; j++) {
      const out = buf[i]!;
      wet[j]! += out;
      // One-pole lowpass inside the feedback loop: each pass round the room
      // loses its top end, so a cymbal dies before a drum does.
      lp = out * (1 - damp) + lp * damp;
      buf[i] = src[j]! + lp * 0.76;
      i = (i + 1) % d;
    }
  }
  for (let j = 0; j < n; j++) wet[j]! /= combs.length;

  // Two allpasses: they change phase, not amplitude, which turns the combs'
  // discrete echoes into something closer to a wash.
  for (const d of [389, 127]) {
    const buf = new Float64Array(d);
    let i = 0;
    for (let j = 0; j < n; j++) {
      const bufOut = buf[i]!;
      const input = wet[j]!;
      wet[j] = -input + bufOut;
      buf[i] = input + bufOut * 0.5;
      i = (i + 1) % d;
    }
  }

  const out = new Float64Array(n);
  for (let j = 0; j < n; j++) out[j] = src[j]! * (1 - mix) + wet[j]! * mix;
  return out;
}

/** Peak-normalise, then a gentle soft clip so nothing ever crackles. */
export function finish(buf: Buf, peak = 0.89): Buf {
  let max = 0;
  for (const v of buf) max = Math.max(max, Math.abs(v));
  const k = max > 0 ? peak / max : 1;
  const out = make(buf.length / RATE);
  for (let i = 0; i < buf.length; i++) out[i] = Math.tanh(buf[i]! * k * 1.1) * 0.95;
  // 6ms fade at each end, so the file itself can never click.
  const f = seconds(0.006);
  for (let i = 0; i < f; i++) {
    out[i]! *= i / f;
    out[out.length - 1 - i]! *= i / f;
  }
  return out;
}

export function wav(buf: Buf): Buffer {
  const data = Buffer.alloc(buf.length * 2);
  for (let i = 0; i < buf.length; i++)
    data.writeInt16LE(Math.max(-32768, Math.min(32767, Math.round(buf[i]! * 32767))), i * 2);
  const head = Buffer.alloc(44);
  head.write("RIFF", 0);
  head.writeUInt32LE(36 + data.length, 4);
  head.write("WAVEfmt ", 8);
  head.writeUInt32LE(16, 16);
  head.writeUInt16LE(1, 20);
  head.writeUInt16LE(1, 22);
  head.writeUInt32LE(RATE, 24);
  head.writeUInt32LE(RATE * 2, 28);
  head.writeUInt16LE(2, 32);
  head.writeUInt16LE(16, 34);
  head.write("data", 36);
  head.writeUInt32LE(data.length, 40);
  return Buffer.concat([head, data]);
}

/* ── two more voices, for the weight ──────────────────────────────── */

/**
 * A band-limited sawtooth.
 *
 * Summed harmonics rather than a naive ramp: a ramp aliases — every partial
 * above half the sample rate folds back down as an inharmonic whine — and
 * this is the voice that carries the chord, so it is the one that must not
 * buzz. The harmonic count is capped per note, so a high voice has fewer.
 */
export function sawAt(freq: number, t: number): number {
  const n = Math.max(1, Math.min(34, Math.floor(RATE / 2 / freq)));
  let v = 0;
  for (let k = 1; k <= n; k++) v += Math.sin(2 * Math.PI * k * freq * t) / k;
  return v * 0.55;
}

/**
 * The brass-ish voice: detuned saws through a lowpass that OPENS.
 *
 * A filter sweeping upward as the note starts is most of what "big" sounds
 * like — it is a brass section leaning into a note, and it is why a static
 * waveform reads as a beep however loud you make it.
 *
 * Three voices a few cents apart, because one oscillator is thin and two is
 * an audible beat. `swell` is the slow attack that makes a note arrive
 * rather than appear.
 */
export function brass(
  freq: number,
  dur: number,
  { gain = 1, swell = 0.05, decay = 1.6, open = 3.4, sub = 0.3 } = {},
): Buf {
  const n = seconds(dur);
  const out = make(dur);
  const detune = [-0.004, 0, 0.0045];
  let lp1 = 0;
  let lp2 = 0;
  for (let i = 0; i < n; i++) {
    const t = i / RATE;
    let v = 0;
    for (const d of detune) v += sawAt(freq * (1 + d), t);
    v /= detune.length;
    if (sub > 0) v += Math.sin(2 * Math.PI * (freq / 2) * t) * sub;

    // Cutoff rides from an octave above the note up to `open` octaves,
    // fastest at the start.
    const k = 1 - Math.exp((-7 * i) / n);
    const cutoff = Math.min(16000, freq * 2 * Math.pow(2, open * k));
    const c = Math.min(1, (2 * Math.PI * cutoff) / RATE);
    lp1 += c * (v - lp1);
    lp2 += c * (lp1 - lp2);

    const a = Math.min(1, t / swell);
    out[i] = lp2 * a * Math.exp((-decay * i) / n) * gain;
  }
  return out;
}

/** Wide detuned voices with a slow attack. Warmth under a landing. */
export function choir(freq: number, dur: number, { gain = 1, swell = 0.12, decay = 2.2 } = {}): Buf {
  const n = seconds(dur);
  const out = make(dur);
  const voices = [-0.007, -0.003, 0, 0.003, 0.007];
  for (let i = 0; i < n; i++) {
    const t = i / RATE;
    let v = 0;
    for (const d of voices) {
      const f = freq * (1 + d);
      v += Math.sin(2 * Math.PI * f * t) + 0.2 * Math.sin(4 * Math.PI * f * t);
    }
    const a = Math.min(1, t / swell);
    out[i] = (v / voices.length) * a * Math.exp((-decay * i) / n) * gain * 0.6;
  }
  return out;
}

/* ── a voice that actually sings ───────────────────────────────────── */

/**
 * ═══ WHY `choir` WAS NOT ENOUGH, AND WHAT A SUNG VOWEL ACTUALLY IS ═══
 *
 * Or, about the Siren: *"it needs to be COMPLETELY regenerated, the singing,
 * in a beautiful soprano opera voice. Our recordings are only a reference
 * for the melody itself."*
 *
 * `choir` above is five detuned sines with one harmonic. That is a warm PAD
 * — it is what sits under a landing — and it is not a person. Three things
 * are missing, and all three are what the ear uses to decide it is hearing
 * somebody sing:
 *
 *   A GLOTTAL SOURCE. A voice is not a sine. It is a buzz, rich in
 *     harmonics, which the throat then filters. Here it is a summed harmonic
 *     series with a -12dB/octave roll-off, which is roughly what a vocal fold
 *     actually produces.
 *
 *   FORMANTS. This is the whole thing. A vowel is not a pitch — it is two or
 *     three RESONANCES at fixed frequencies that stay put while the pitch
 *     moves underneath them. /i/ is a low first formant and a very high
 *     second; /a/ has them close together in the middle. Sing the same note
 *     through different formants and you get different vowels, which is how
 *     this file can make a voice say "si-re-na" with no recording involved.
 *
 *   VIBRATO. An operatic voice oscillates about 5.5 times a second by
 *     roughly a third of a semitone. Without it the line is a synthesiser;
 *     with it, it is a singer. It is the single cheapest thing here and it
 *     does more than the other two.
 *
 * The formants below are soprano values. They are higher and wider apart
 * than a speaking voice's, which is why a soprano is hard to understand and
 * why this one leans on the long /a/ at the end of each phrase.
 */
/**
 * Each vowel as three resonances AND their three levels.
 *
 * ⚠ THE LEVELS ARE HALF THE VOWEL, which the first version of this got
 * wrong. With one shared balance of [1, 0.42, 0.18] every vowel came out
 * measuring the same: the second formant sat 17dB under the first and the
 * bands around 1150, 1700 and 2000 all held under 1% of the energy whatever
 * was asked for. A formant nobody can hear is not a formant.
 *
 * In a real /i/ the second formant is only a few dB below the first — that
 * brightness IS the vowel. In /a/ the two sit close together in frequency
 * and the second is well down. So the balance travels with the frequencies.
 *
 * ⚠ `g` IS NOT IN DECIBELS AND IS NOT A RATIO OF LEVELS. It is a multiplier
 * on a resonator whose own output is already scaled by `(1 - r)`, and the
 * upper formants are driven by harmonics that are themselves 10-18dB down
 * before they arrive. So the numbers that LOOK right — 1, 0.8, 0.34 for /i/
 * — measured as less than one per cent of the energy above a kilohertz, and
 * the voice came out dark. These are calibrated against the spectrum of the
 * finished file instead, which is the only thing that can be checked without
 * ears.
 */
export const VOWELS = {
  /** "si" — closed and bright: a very high second formant, almost as loud. */
  ee: { f: [350, 2000, 2800], g: [1, 5.0, 2.1] },
  /** "re" — half open. */
  eh: { f: [500, 1700, 2500], g: [1, 3.8, 1.5] },
  /** "na" — wide open, and the one an audience actually hears. */
  ah: { f: [800, 1150, 2800], g: [1, 2.8, 0.9] },
} as const;

export type Vowel = keyof typeof VOWELS;

/**
 * One sung note: a soprano on `freq`, shaped into `vowel`.
 *
 * `slideFrom` starts the note at another pitch and glides to this one over
 * the first fifth of its length — a singer reaching a note from below, and
 * the thing that keeps a sequence of notes from sounding typed in.
 */
export function soprano(
  freq: number,
  dur: number,
  {
    vowel = "ah" as Vowel,
    gain = 1,
    swell = 0.09,
    decay = 0.6,
    /** Depth in cents. 35 is operatic; 0 is a synthesiser. */
    vibrato = 35,
    vibratoHz = 5.5,
    slideFrom = 0,
  } = {},
): Buf {
  const n = seconds(dur);
  const out = make(dur);
  const [f1, f2, f3] = VOWELS[vowel].f;
  const level = VOWELS[vowel].g;
  /*
   * ═══ FORMANT TUNING, WHICH IS WHY SOPRANOS SOUND LIKE SOPRANOS ═══
   *
   * ⚠ A RESONANCE BELOW THE FUNDAMENTAL CANNOT SOUND. There is no harmonic
   * down there to excite it. Measured on the first render of the Siren: four
   * of the six notes asked for a first formant under their own fundamental
   * — /i/ wants 350Hz and F#5 is 740 — so those four notes were being shaped
   * by whatever harmonic happened to sit nearest, and the vowels were mush.
   *
   * Real sopranos have exactly this problem and exactly this answer: they
   * RAISE the first formant to meet the note. It is why every vowel drifts
   * toward /a/ as a soprano climbs, and why a high aria is hard to make out
   * even sung by somebody magnificent.
   *
   * So F1 is lifted to the fundamental when it would fall below it, and the
   * vowel keeps its identity in F2 and F3 — which are high enough to speak
   * at any note in this range. /i/ at F#5 is no longer a low F1; it is a
   * 2kHz second formant over an open throat, which is what it really is.
   */
  const tunedF1 = Math.max(f1, freq * 1.02);
  // Three two-pole resonators, one per formant. `r` near 1 is a narrow,
  // ringing peak — which is what a throat is.
  const res = [tunedF1, f2, f3].map((f, i) => ({
    w: (2 * Math.PI * f) / RATE,
    r: [0.986, 0.976, 0.968][i]!,
    g: level[i]!,
    y1: 0,
    y2: 0,
  }));
  let phase = 0;
  for (let i = 0; i < n; i++) {
    const t = i / RATE;
    const k = i / n;
    /*
     * The pitch for this sample: the note, plus the reach up into it, plus
     * the vibrato — which fades IN over the first fifth, because a singer
     * does not start wobbling on the attack.
     */
    const reach = slideFrom > 0 && k < 0.2 ? Math.pow(1 - k / 0.2, 2) : 0;
    const base = freq * Math.pow(slideFrom / freq, reach);
    const vib = vibrato * Math.min(1, k / 0.2) * Math.sin(2 * Math.PI * vibratoHz * t);
    const f = base * Math.pow(2, vib / 1200);

    /*
     * The glottal buzz.
     *
     * ⚠ 1/h AND NOT 1/h². The comment above this used to say -12dB/octave
     * and the code said 1/h², which is -12dB per HARMONIC — by the third one
     * it is 19dB down. Measured on the first render: every band above 1kHz
     * held under 2% of the energy, so the formants had nothing to shape and
     * the "soprano" was a sine with vibrato on it. A theremin.
     *
     * 1/h is the real figure for a vocal fold: -6dB per octave of harmonic
     * number, which leaves a bright buzz for the throat to work on. The
     * difference between this line and the last one is the difference
     * between a voice and a tone.
     */
    phase += (2 * Math.PI * f) / RATE;
    if (phase > 2 * Math.PI) phase -= 2 * Math.PI;
    let src = 0;
    for (let h = 1; h <= 24; h++) {
      if (f * h > RATE / 2.2) break;
      src += Math.sin(phase * h) / h;
    }

    // Through the throat.
    let v = 0;
    for (const o of res) {
      const y = src + 2 * o.r * Math.cos(o.w) * o.y1 - o.r * o.r * o.y2;
      o.y2 = o.y1;
      o.y1 = y;
      v += y * (1 - o.r) * o.g;
    }

    /*
     * Held, not struck. A sung note barely decays while the breath lasts, so
     * the default decay is a tenth of a bell's — and it releases at the end
     * rather than stopping, or the join to the next note is a click.
     */
    const a = Math.min(1, t / swell);
    const release = k > 0.86 ? (1 - k) / 0.14 : 1;
    out[i] = v * a * release * Math.exp((-decay * i) / n) * gain;
  }
  return out;
}

/* ── the idents ────────────────────────────────────────────────────── */
